//! Current-term rankings retain exact totals and distinct entity identities.
use super::{
    entity_details::{DeclaredGbpPeriodTotal, MemberDeclaration},
    funder::{FunderId, FunderKind},
    parliament_member::MemberId,
};

/// Minimal member identity in a ranking.
#[derive(Clone, Debug)]
pub struct RankedMember {
    /// Parliament identity.
    pub id: MemberId,
    /// Latest stored name.
    pub name: String,
    /// Latest party label.
    pub party_name: String,
    /// Latest constituency or membership description.
    pub membership_from: String,
}
/// Canonical funder identity and classification.
#[derive(Clone, Debug)]
pub struct RankedFunder {
    /// Canonical alias-group identity.
    pub id: FunderId,
    /// Preferred group name.
    pub name: String,
    /// Canonical root classification.
    pub kind: FunderKind,
}
/// Recipient's latest party identity.
#[derive(Clone, Debug)]
pub struct RankedParty {
    /// Stored party identity.
    pub id: i32,
    /// Deterministic label across recipients.
    pub name: String,
}
/// A ranked identity and its backend-owned financial total.
#[derive(Debug)]
pub struct Ranking<I> {
    /// Entity being ranked.
    pub identity: I,
    /// Exact declared GBP total and coverage.
    pub total: DeclaredGbpPeriodTotal,
}
/// Four top-ten boards from one snapshot for the selected period.
#[derive(Debug)]
pub struct Rankings {
    /// Scope shared by all boards.
    pub period: super::reporting_period::ReportingPeriod,
    /// Inclusive current-term boundary, independent of the selected period.
    pub current_term_start: chrono::DateTime<chrono::Utc>,
    /// All-category member totals.
    pub members: Vec<Ranking<RankedMember>>,
    /// Donation/support totals from canonical individual funders.
    pub individuals: Vec<Ranking<RankedFunder>>,
    /// Donation/support totals from all canonical non-individual funders, including unclassified.
    pub companies: Vec<Ranking<RankedFunder>>,
    /// Donation/support declared by recipient MPs' latest party.
    pub parties: Vec<Ranking<RankedParty>>,
}
/// One declaration with canonical funder metadata keyed by entry references.
pub struct RankingDeclaration {
    /// Recipient member.
    pub member: RankedMember,
    /// Recipient's latest party.
    pub party: RankedParty,
    /// Each stored funding occurrence, including unnamed entries.
    pub declaration: MemberDeclaration,
    /// Canonical funders referenced by the declaration entries.
    pub funders: std::collections::BTreeMap<uuid::Uuid, RankedFunder>,
}
//! Bulk ranking fact reads.
use crate::domain::models::rankings::RankingDeclaration;
use thiserror::Error;
/// Rankings persistence boundary.
pub trait RankingsRepo: Clone + Send + Sync + 'static {
    /// Reads each declaration and funding occurrence once in one snapshot.
    fn ranking_declarations(
        &self,
        window: crate::domain::models::reporting_period::RegistrationWindow,
    ) -> impl Future<Output = Result<Vec<RankingDeclaration>, RankingsError>> + Send;
}
/// Private database and stored-data diagnostics.
#[derive(Debug, Error)]
#[error("rankings read failed: {0}")]
pub struct RankingsError(pub String);
use super::currency::CURRENCY_WHITESPACE;
use crate::{
    domain::{
        models::{
            entity_details::{
                DeclarationCategory, DeclaredFunding, FunderReference, MemberDeclaration,
            },
            funder::{FunderId, FunderKind},
            rankings::{RankedFunder, RankedMember, RankedParty, RankingDeclaration},
        },
        repositories::rankings::{RankingsError, RankingsRepo},
    },
    outbound::ExposedDatabase,
};
use std::str::FromStr;

impl From<sqlx::Error> for RankingsError {
    fn from(error: sqlx::Error) -> Self {
        Self(error.to_string())
    }
}

fn timestamp(date: chrono::DateTime<chrono::Utc>) -> Result<time::OffsetDateTime, RankingsError> {
    time::OffsetDateTime::from_unix_timestamp_nanos(
        i128::from(date.timestamp()) * 1_000_000_000 + i128::from(date.timestamp_subsec_nanos()),
    )
    .map_err(|error| RankingsError(error.to_string()))
}

impl RankingsRepo for ExposedDatabase {
    async fn ranking_declarations(
        &self,
        window: crate::domain::models::reporting_period::RegistrationWindow,
    ) -> Result<Vec<RankingDeclaration>, RankingsError> {
        let start = window.start().map(timestamp).transpose()?;
        let end = window.end().map(timestamp).transpose()?;
        let rows = sqlx::query!(
            "SELECT m.parliament_member_id, m.name, m.party_id, m.party_name, m.latest_membership_from,
                d.source_declaration_id, d.category_id, d.category_name, d.registration_date,
                e.id AS \"entry_id?\", e.amount, NULLIF(btrim(e.currency, $3), '') AS currency,
                f.id AS \"funder_id?\", COALESCE(n.preferred_name, f.funder_name) AS funder_name, f.funder_kind
             FROM exposed.declarations d
             JOIN exposed.members m ON m.id = d.member_id
             LEFT JOIN exposed.funding_entries e ON e.source_declaration_id = d.source_declaration_id
             LEFT JOIN exposed.funder_alias_groups g ON g.funder_id = e.funder_id
             LEFT JOIN exposed.funders f ON f.id = COALESCE(g.group_id, e.funder_id)
             LEFT JOIN exposed.funder_group_names n ON n.group_id = f.id
             WHERE ($1::timestamptz IS NULL OR d.registration_date >= $1)
               AND ($2::timestamptz IS NULL OR d.registration_date < $2)
             ORDER BY d.source_declaration_id, e.id",
            start, end, CURRENCY_WHITESPACE
        ).fetch_all(self.pool()).await?;
        let mut declarations: Vec<RankingDeclaration> = Vec::new();
        for row in rows {
            if declarations
                .last()
                .is_none_or(|source| source.declaration.source_id != row.source_declaration_id)
            {
                declarations.push(RankingDeclaration {
                    member: RankedMember {
                        id: row.parliament_member_id.to_string().parse().map_err(
                            |error: crate::domain::models::parliament_member::MemberIdError| {
                                RankingsError(error.to_string())
                            },
                        )?,
                        name: row.name,
                        party_name: row.party_name.clone(),
                        membership_from: row.latest_membership_from,
                    },
                    party: RankedParty {
                        id: row.party_id,
                        name: row.party_name,
                    },
                    declaration: MemberDeclaration {
                        source_id: row.source_declaration_id,
                        category: DeclarationCategory::from_source_id(row.category_id),
                        category_name: row.category_name,
                        registered_at: row
                            .registration_date
                            .map(|date| {
                                chrono::DateTime::from_timestamp(
                                    date.unix_timestamp(),
                                    date.nanosecond(),
                                )
                                .ok_or_else(|| {
                                    RankingsError("Stored registration date is out of range".into())
                                })
                            })
                            .transpose()?,
                        entries: Vec::new(),
                    },
                    funders: std::collections::BTreeMap::new(),
                });
            }
            if row.entry_id.is_some() {
                let funder = row
                    .funder_id
                    .zip(row.funder_name)
                    .map(|(id, name)| {
                        let kind = row
                            .funder_kind
                            .as_deref()
                            .map_or(Ok(FunderKind::NotSpecified), FunderKind::from_str)
                            .map_err(|error| RankingsError(error.to_string()))?;
                        Ok::<_, RankingsError>(RankedFunder {
                            id: FunderId::new(id),
                            name,
                            kind,
                        })
                    })
                    .transpose()?;
                if let Some(source) = declarations.last_mut() {
                    source.declaration.entries.push(DeclaredFunding {
                        funder: funder.as_ref().map(|funder| FunderReference {
                            id: funder.id,
                            name: funder.name.clone(),
                        }),
                        payment_type: None,
                        amount: row.amount,
                        currency: row.currency,
                    });
                    if let Some(funder) = funder {
                        source.funders.insert(funder.id.value(), funder);
                    }
                }
            }
        }
        Ok(declarations)
    }
}

